package uptimescout
import("context";"encoding/json";"errors";"fmt";"io";"net/http";"net/url";"strings";"time")
type Client struct{Key string;BaseURL string;HTTP *http.Client}
func New(key string)*Client{return &Client{Key:key,BaseURL:"https://api.uptimescout.com",HTTP:&http.Client{Timeout:30*time.Second,CheckRedirect:func(r *http.Request,v []*http.Request)error{return http.ErrUseLastResponse}}}}
func(c *Client)Request(ctx context.Context,method string,params url.Values)(map[string]any,error){if c.Key==""||strings.ContainsAny(c.Key,"\r\n"){return nil,errors.New("license key required")};valid:=map[string]bool{"services":true,"status":true,"statuses":true,"summary":true,"history":true,"stats":true,"incidents":true};if !valid[method]{return nil,errors.New("unknown method")};req,err:=http.NewRequestWithContext(ctx,"GET",strings.TrimRight(c.BaseURL,"/")+"/v1/"+method+"?"+params.Encode(),nil);if err!=nil{return nil,err};req.Header.Set("Authorization","Bearer "+c.Key);req.Header.Set("Accept","application/json");resp,err:=c.HTTP.Do(req);if err!=nil{return nil,errors.New("UptimeScout connection failed")};defer resp.Body.Close();if resp.StatusCode!=200{return nil,fmt.Errorf("UptimeScout HTTP %d",resp.StatusCode)};raw,err:=io.ReadAll(io.LimitReader(resp.Body,4*1024*1024+1));if err!=nil{return nil,err};if len(raw)>4*1024*1024{return nil,errors.New("response too large")};var out map[string]any;err=json.Unmarshal(raw,&out);return out,err}
